.mes_text .custom-nemo-vn {
  display: block;
  box-sizing: border-box;
  max-width: 100%;
  margin: 1.4rem 0;
  padding: 0;
  overflow: visible;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: #f4edf9;
  box-shadow: none;
  font-family: inherit;
  text-align: left;
  color-scheme: dark;
  isolation: isolate;
}

.mes_text .custom-nemo-vn * {
  box-sizing: border-box;
}

.mes_text .custom-nemo-vn-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 18px;
  color: #c8b1e6;
  font: 600 .68rem/1.4 system-ui,sans-serif;
  letter-spacing: .16em;
  text-transform: uppercase;
}

.mes_text .custom-nemo-vn-heading span:last-child {
  font-weight: 400;
  letter-spacing: .04em;
  text-transform: none;
  color: #b3a5c5;
}

.mes_text .custom-nemo-vn-slide {
  display: block;
  position: relative;
  min-width: 0;
  padding-top: 260px;
}

.mes_text .custom-nemo-vn-window {
  display: flex;
  position: relative;
  z-index: 0;
  isolation: isolate;
  flex-direction: column;
  min-width: 0;
  min-height: 240px;
  overflow: visible;
  border: 0;
  border-radius: 16px;
  background: transparent;
  color: #f4edf9;
}

.mes_text .custom-nemo-vn-window::before {
  content: "";
  display: block;
  position: absolute;
  z-index: 0;
  inset: 0;
  border: 1px solid #ad8bd2;
  border-radius: 16px;
  background: linear-gradient(145deg,rgba(35,25,49,.98),rgba(20,17,29,.98));
  box-shadow: 0 10px 30px #0005,inset 0 1px 0 #e7d0ff18;
  pointer-events: none;
}

.mes_text .custom-nemo-vn-card {
  display: block;
  position: relative;
  min-width: 0;
  max-width: 100%;
  margin: 18px 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: #f4edf9;
  overflow-wrap: anywhere;
  text-align: left;
}

.mes_text .custom-nemo-vn .custom-nemo-vn-card {
  display: contents;
}

.mes_text .custom-nemo-vn-portrait {
  display: flex;
  position: relative;
  z-index: 0;
  align-items: flex-end;
  justify-content: center;
  width: 100%;
  min-width: 0;
  margin: 0 auto -220px;
  padding: 0;
  border: 0;
  background: transparent;
  pointer-events: none;
}

.mes_text .custom-nemo-vn-portrait img {
  display: block;
  width: auto;
  max-width: 100%;
  height: auto;
  max-height: 510px;
  object-fit: contain;
  object-position: center bottom;
  margin: 0;
  filter: drop-shadow(0 8px 15px #0004);
}

.mes_text .custom-nemo-vn .custom-nemo-vn-portrait {
  position: absolute;
  z-index: -1;
  top: -260px;
  left: 0;
  width: 100%;
  height: 500px;
  margin: 0;
  padding: 0;
}

.mes_text .custom-nemo-vn .custom-nemo-vn-portrait img {
  width: auto!important;
  max-width: 100%!important;
  height: 500px!important;
  max-height: none;
}

.mes_text .custom-nemo-vn-speech {
  display: block;
  position: relative;
  z-index: 1;
  min-width: 0;
  margin: 0;
  padding: 22px 24px;
  border: 1px solid #ad8bd2;
  border-radius: 15px;
  background: rgba(28,21,39,.98);
}

.mes_text .custom-nemo-vn .custom-nemo-vn-speech {
  flex: 1 1 auto;
  padding: 34px 26px 13px;
  border: 0;
  border-radius: 0;
  background: transparent;
}

.mes_text .custom-nemo-vn-name {
  display: block;
  width: fit-content;
  max-width: calc(100% - 36px);
  margin: 0 0 13px;
  font-family: inherit;
  font-weight: 700;
  font-size: 1rem;
  line-height: 1.35;
  color: #e5ccff;
  letter-spacing: .01em;
  overflow-wrap: anywhere;
}

.mes_text .custom-nemo-vn .custom-nemo-vn-name {
  position: absolute;
  z-index: 2;
  top: -20px;
  left: 20px;
  margin: 0;
  padding: 8px 18px;
  border: 1px solid #bb96df;
  border-radius: 9px;
  background: linear-gradient(135deg,#493259,#2a2038);
  box-shadow: 0 4px 12px #0004;
  font-size: .94rem;
}

.mes_text .custom-nemo-vn-dialogue {
  display: block;
  margin: 0;
  white-space: pre-wrap;
  font-family: inherit;
  font-size: 1rem;
  line-height: 1.65;
  color: #f4edf9;
  overflow-wrap: anywhere;
}

.mes_text .custom-nemo-vn-nav {
  display: none;
  position: relative;
  z-index: 1;
  align-items: center;
  justify-content: space-between;
  flex: 0 0 auto;
  gap: 10px;
  min-height: 66px;
  margin: 0;
  padding: 9px 20px 14px;
}

.mes_text .custom-nemo-vn-control {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-width: 90px;
  min-height: 42px;
  margin: 0;
  padding: 9px 13px;
  border: 1px solid #b394d077;
  border-radius: 9px;
  background: #352543;
  color: #f7f1ff;
  font: 600 .8rem/1.25 system-ui,sans-serif;
  cursor: pointer;
  user-select: none;
}

.mes_text .custom-nemo-vn-control:hover {
  background: #493259;
  border-color: #d4b4f3;
}

.mes_text .custom-nemo-vn-control:focus-within {
  outline: 2px solid #dfc6ff;
  outline-offset: 3px;
}

.mes_text .custom-nemo-vn-control input {
  position: absolute;
  inset: 0;
  display: block;
  opacity: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  cursor: pointer;
}

.mes_text .custom-nemo-vn-counter {
  color: #b5a4c6;
  font: 500 .73rem/1.4 system-ui,sans-serif;
  letter-spacing: .12em;
  white-space: nowrap;
}

.mes_text .custom-nemo-vn-edge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 90px;
  min-height: 42px;
  color: #90829f;
  font: 500 .75rem/1.3 system-ui,sans-serif;
}

.mes_text .custom-nemo-vn-text-only .custom-nemo-vn-speech {
  padding: 22px 24px;
}

.mes_text .custom-nemo-vn-legacy {
  display: block;
  margin: 12px 0;
  padding: 12px 16px;
  border-left: 3px solid #ac83d7;
  border-radius: 8px;
  background: #241b2d;
  color: #e8dcef;
  font: inherit;
  line-height: 1.55;
  overflow-wrap: anywhere;
}

@supports selector(:has(input:checked)) {
  .mes_text .custom-nemo-vn .custom-nemo-vn-slide {
    display: none;
  }

  .mes_text .custom-nemo-vn:not(:has(input:checked)) .custom-nemo-vn-slide-1,
  .mes_text .custom-nemo-vn:has(.custom-nemo-vn-to-1:checked) .custom-nemo-vn-slide-1,
  .mes_text .custom-nemo-vn:has(.custom-nemo-vn-to-2:checked) .custom-nemo-vn-slide-2,
  .mes_text .custom-nemo-vn:has(.custom-nemo-vn-to-3:checked) .custom-nemo-vn-slide-3,
  .mes_text .custom-nemo-vn:has(.custom-nemo-vn-to-4:checked) .custom-nemo-vn-slide-4 {
    display: block;
  }

  .mes_text .custom-nemo-vn .custom-nemo-vn-nav {
    display: flex;
  }

  .mes_text .custom-nemo-vn-portrait:not(:has(img)) {
    display: none;
  }

  .mes_text .custom-nemo-vn-slide:not(:has(.custom-nemo-vn-portrait img)) {
    padding-top: 22px;
  }

  .mes_text .custom-nemo-vn-slide:not(:has(.custom-nemo-vn-portrait img)) .custom-nemo-vn-window {
    min-height: 0;
  }

  .mes_text .custom-nemo-vn-card:not(:has(.custom-nemo-vn-portrait img)) .custom-nemo-vn-speech {
    min-height: 0;
  }
}

@media (max-width:520px) {
  .mes_text .custom-nemo-vn {
    margin: 1rem 0;
  }

  .mes_text .custom-nemo-vn-slide {
    padding-top: 220px;
  }

  .mes_text .custom-nemo-vn-window {
    min-height: 210px;
    border-radius: 13px;
  }

  .mes_text .custom-nemo-vn-window::before {
    border-radius: 13px;
  }

  .mes_text .custom-nemo-vn .custom-nemo-vn-portrait {
    top: -220px;
    height: 430px;
  }

  .mes_text .custom-nemo-vn .custom-nemo-vn-portrait img {
    height: 430px!important;
  }

  .mes_text .custom-nemo-vn .custom-nemo-vn-speech {
    padding: 32px 17px 9px;
  }

  .mes_text .custom-nemo-vn .custom-nemo-vn-name {
    top: -19px;
    left: 13px;
    padding: 8px 13px;
    max-width: calc(100% - 26px);
    font-size: .84rem;
  }

  .mes_text .custom-nemo-vn-dialogue {
    font-size: .92rem;
    line-height: 1.58;
  }

  .mes_text .custom-nemo-vn-nav {
    padding: 8px 12px 12px;
    gap: 7px;
    min-height: 62px;
  }

  .mes_text .custom-nemo-vn-control,
  .mes_text .custom-nemo-vn-edge {
    min-width: 78px;
    min-height: 42px;
    font-size: .72rem;
    padding: 9px 10px;
  }

  .mes_text .custom-nemo-vn-heading {
    padding: 11px 13px;
    font-size: .62rem;
    gap: 8px;
  }

  .mes_text .custom-nemo-vn-heading span:last-child {
    font-size: .62rem;
  }
}

@media (prefers-reduced-motion:no-preference) {
  .mes_text .custom-nemo-vn-control {
    transition: background .15s ease,border-color .15s ease;
  }
